uintptr_t CTIM_Callback(uint32_t i,uint32_t custom){if(!custom)return 0;switch(i){case 0:return (uintptr_t)(custom==1?HAL_TIM_Base_MspInit:Custom0);case 1:return (uintptr_t)(custom==1?HAL_TIM_Base_MspDeInit:Custom1);case 2:return (uintptr_t)(custom==1?HAL_TIM_IC_MspInit:Custom2);case 3:return (uintptr_t)(custom==1?HAL_TIM_IC_MspDeInit:Custom3);case 4:return (uintptr_t)(custom==1?HAL_TIM_OC_MspInit:Custom4);case 5:return (uintptr_t)(custom==1?HAL_TIM_OC_MspDeInit:Custom5);case 6:return (uintptr_t)(custom==1?HAL_TIM_PWM_MspInit:Custom6);case 7:return (uintptr_t)(custom==1?HAL_TIM_PWM_MspDeInit:Custom7);case 8:return (uintptr_t)(custom==1?HAL_TIM_OnePulse_MspInit:Custom8);case 9:return (uintptr_t)(custom==1?HAL_TIM_OnePulse_MspDeInit:Custom9);case 10:return (uintptr_t)(custom==1?HAL_TIM_Encoder_MspInit:Custom10);case 11:return (uintptr_t)(custom==1?HAL_TIM_Encoder_MspDeInit:Custom11);case 12:return (uintptr_t)(custom==1?HAL_TIMEx_HallSensor_MspInit:Custom12);case 13:return (uintptr_t)(custom==1?HAL_TIMEx_HallSensor_MspDeInit:Custom13);case 14:return (uintptr_t)(custom==1?HAL_TIM_PeriodElapsedCallback:Custom14);case 15:return (uintptr_t)(custom==1?HAL_TIM_PeriodElapsedHalfCpltCallback:Custom15);case 16:return (uintptr_t)(custom==1?HAL_TIM_TriggerCallback:Custom16);case 17:return (uintptr_t)(custom==1?HAL_TIM_TriggerHalfCpltCallback:Custom17);case 18:return (uintptr_t)(custom==1?HAL_TIM_IC_CaptureCallback:Custom18);case 19:return (uintptr_t)(custom==1?HAL_TIM_IC_CaptureHalfCpltCallback:Custom19);case 20:return (uintptr_t)(custom==1?HAL_TIM_OC_DelayElapsedCallback:Custom20);case 21:return (uintptr_t)(custom==1?HAL_TIM_PWM_PulseFinishedCallback:Custom21);case 22:return (uintptr_t)(custom==1?HAL_TIM_PWM_PulseFinishedHalfCpltCallback:Custom22);case 23:return (uintptr_t)(custom==1?HAL_TIM_ErrorCallback:Custom23);case 24:return (uintptr_t)(custom==1?HAL_TIMEx_CommutCallback:Custom24);case 25:return (uintptr_t)(custom==1?HAL_TIMEx_CommutHalfCpltCallback:Custom25);case 26:return (uintptr_t)(custom==1?HAL_TIMEx_BreakCallback:Custom26);case 27:return (uintptr_t)(custom==1?HAL_TIMEx_Break2Callback:Custom27);case 28:return (uintptr_t)(custom==1?HAL_TIMEx_EncoderIndexCallback:Custom28);case 29:return (uintptr_t)(custom==1?HAL_TIMEx_DirectionChangeCallback:Custom29);case 30:return (uintptr_t)(custom==1?HAL_TIMEx_IndexErrorCallback:Custom30);case 31:return (uintptr_t)(custom==1?HAL_TIMEx_TransitionErrorCallback:Custom31);default:assert(0);return 0;}}
